      "16": "icon16.png",
      "48": "icon48.png",
      "128": "icon128.png"
    },
    "default_popup": ""
  },
  "background": {
    "service_worker": "background.js"
  }
}
```

**b. background.js**  
This script listens for the extension icon click and saves the page content.

```js
chrome.action.onClicked.addListener((tab) => {
  chrome.scripting.executeScript({
    target: { tabId: tab.id },
    function: getPageContent
  }, (results) => {
    if (results && results[0] && results[0].result) {
      const htmlContent = results[0].result;
      const filename = `page-${Date.now()}.html`;
      const blob = new Blob([htmlContent], { type: 'text/html' });
      const url = URL.createObjectURL(blob);

      chrome.downloads.download({
        url: url,
        filename: filename
      }, () => {
        // Revoke the object URL after download
        setTimeout(() => URL.revokeObjectURL(url), 100);
      });
    }
  });
});

// Function to get the page's outer HTML
function getPageContent() {
  return document.documentElement.outerHTML;
}
```

**c. Icons**  
Add icon files named `icon16.png`, `icon48.png`, and `icon128.png` in the same directory. You can use any icon images you like, or create simple placeholder icons.

---

### 2. Load your extension into Chrome

1. Save all files in a folder, e.g., `save-page-extension/`.
2. Open Chrome and go to `chrome://extensions/`.
3. Enable **Developer mode** (toggle in the top right).
4. Click **Load unpacked** and select your extension folder.
5. You should see your extension icon in the toolbar.

### 3. Usage

Navigate to any webpage, click the extension icon, and it will save the current page as an HTML file to your default downloads folder.

---

### Notes:
- This extension saves the full HTML of the current page, including scripts and styles.
