---

### 3. Initialize the model and handle chat logic

```javascript
(async () => {
  const chatDiv = document.getElementById('chat');
  const inputBox = document.getElementById('userInput');
  const sendBtn = document.getElementById('sendBtn');

  // Load the BlenderBot model
  const modelName = 'facebook/blenderbot-400m-distill';
  const pipeline = await window.transformers.pipeline('conversational', modelName);

  // Maintain chat history if needed
  let conversationHistory = [];

  // Function to add messages to chat display
  function addMessage(text, sender = 'user') {
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message ' + sender;
    messageDiv.textContent = text;
    chatDiv.appendChild(messageDiv);
    chatDiv.scrollTop = chatDiv.scrollHeight; // Scroll to bottom
  }

  // Handle user input
  async function handleUserInput() {
    const userMessage = inputBox.value.trim();
    if (!userMessage) return;

    addMessage(userMessage, 'user');
    inputBox.value = '';

    // Send the message to the model
    try {
      // The pipeline expects an object with 'text' and 'history'
      const response = await pipeline.conversational(userMessage, conversationHistory);

      // The response object contains 'generated_responses' and updated 'history'
      const botReply = response.generated_responses.slice(-1)[0];

      addMessage(botReply, 'bot');

      // Update conversation history for context
      conversationHistory = response.history;
    } catch (err) {
      console.error('Error:', err);
      addMessage('Sorry, there was an error.', 'bot');
    }
  }

  // Event listeners
  sendBtn.addEventListener('click', handleUserInput);
  inputBox.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      handleUserInput();
    }
  });
})();
```

---

### 4. Notes & improvements

- **Performance:** Loading the model may take some time depending on your device. For production, consider loading the model once and managing state.
- **Capabilities:** The `facebook/blenderbot-400m-distill` model is designed for conversational tasks, but its responses may vary.
- **Styling:** Customize the chat UI as needed.
- **Advanced features:** You could add message timestamps, better error handling, or persistent chat history.

---

### Summary

This setup loads the BlenderBot model using transformers.js in vanilla JavaScript, creates a simple chat interface, and handles conversation flow. It allows you to have a basic interactive chat with the model directly in the browser without any frameworks.

