```javascript
const canvas = document.getElementById('circleCanvas');
const ctx = canvas.getContext('2d');
const slider = document.getElementById('radiusSlider');

const centerX = canvas.width / 2;
const centerY = canvas.height / 2;

// Function to draw the circle with concentric markers
function drawCircle(radius) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw concentric circles
  const numberOfMarkers = 4; // Adjust as needed
  ctx.strokeStyle = '#cccccc';
  ctx.lineWidth = 1;

  for (let i = 1; i <= numberOfMarkers; i++) {
    const r = (i / numberOfMarkers) * radius;
    ctx.beginPath();
    ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Draw main circle
  ctx.fillStyle = '#66ccff';
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fill();

  // Optional: draw a border around the main circle
  ctx.strokeStyle = '#333333';
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Initial draw
let currentRadius = parseInt(slider.value);
drawCircle(currentRadius);

// Update circle when slider value changes
slider.addEventListener('input', () => {
  currentRadius = parseInt(slider.value);
  drawCircle(currentRadius);
});
```

### 3. How it works:
