Certainly! Below is a simple example of C++ code that creates a TCP socket, binds it to port 888, and reads data from incoming network connections. This example uses the Berkeley sockets API, which is common on Unix-like systems (Linux, macOS). If you're on Windows, you'd need to initialize Winsock with `WSAStartup` and use `closesocket` instead of `close`.

**Note:** Make sure your program has the necessary permissions to bind to the port and that port 888 is not already in use.

```cpp
#include <iostream>
#include <cstring>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h> // for close()

int main() {
    const int port = 888;
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    const int buffer_size = 1024;
    char buffer[buffer_size];

    // 1. Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket failed");
        return 1;
    }

    // 2. Bind the socket to port 888
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    address.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) == -1) {
        perror("bind failed");
        close(server_fd);
        return 1;
    }

    // 3. Listen for incoming connections
    if (listen(server_fd, 3) == -1) {
        perror("listen failed");
        close(server_fd);
        return 1;
    }

    std::cout << "Listening on port " << port << "...\n";

    // 4. Accept incoming connection
    while (true) {
        std::cout << "Waiting for a connection...\n";
        new_socket = accept(server_fd, (struct sockaddr*)&address, (socklen_t*)&addrlen);
        if (new_socket == -1) {
            perror("accept failed");
            continue; // Try accepting next connection
        }

        std::cout << "Connection accepted.\n";

        // 5. Read data from the socket
        ssize_t bytes_read;
        while ((bytes_read = read(new_socket, buffer, buffer_size - 1)) > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            std::cout << "Received: " << buffer << std::endl;
        }

        if (bytes_read == -1) {
            perror("read failed");
        }

        close(new_socket);
        std::cout << "Connection closed.\n";
    }

    // Close the server socket (unreachable in this example)
    close(server_fd);
    return 0;
}
```

### How it works:
- Creates a TCP listening socket on port 888.
- Waits for incoming client connections.
- Accepts each connection and reads data, printing it to the console.
- Closes each client connection after reading.

### Notes:
- This is a basic example; for production code, consider adding error handling, multi-threading, or asynchronous I/O.
- On Windows, replace socket functions with their Winsock equivalents and initialize Winsock with `WSAStartup()`.

