Certainly! Merging Word documents with specific requirements using the OpenXML SDK can be quite involved. Here's a high-level approach and a sample implementation to get you started:

### Approach:
1. **Open both documents** using OpenXML SDK.
2. **Extract the first 2 pages** (including headers, footers, styles, fonts, images) from the **first document**.
3. **Extract only the content (body)** and glossary from the **second document**.
4. **Merge** the extracted parts into a new document, maintaining styles, images, headers, and footers where required.
5. Handle images and embedded resources properly so that they are included in the merged document.

### Important notes:
- Word documents are complex; pages are not explicitly stored—they are determined by layout during rendering. To extract pages, you typically extract content up to a certain point, which can be tricky.
- For simplicity, this implementation will assume:
  - You have control over the content, and can split content based on paragraphs or bookmarks.
  - You can identify the start/end of pages using some markers or by paragraph counts (a rough approximation).

---

### Sample Implementation in C#

```csharp
using System;
using System.IO;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public class WordMerger
{
    public static void MergeDocuments(string firstDocPath, string secondDocPath, string outputPath)
    {
        // Create a new document
        using (WordprocessingDocument newDoc = WordprocessingDocument.Create(outputPath, DocumentFormat.OpenXml.WordprocessingDocumentType.Document))
        {
            MainDocumentPart mainPart = newDoc.AddMainDocumentPart();
            mainPart.Document = new Document(new Body());

            // Copy styles, fonts, themes, headers, footers from first document
            CopyStylesAndResources(firstDocPath, mainPart);

            // Extract first 2 pages content from first document
            var firstDocContent = ExtractPagesContent(firstDocPath, 2);

            // Extract body content and glossary from second document
            var secondDocContent = ExtractBodyAndGlossary(secondDocPath);

            // Append the first document content
            AppendContent(mainPart, firstDocContent);

            // Append the second document content (body + glossary)
            AppendContent(mainPart, secondDocContent);
        }

        Console.WriteLine("Documents merged successfully.");
    }

    private static void CopyStylesAndResources(string sourcePath, MainDocumentPart destinationMainPart)
    {
        using (WordprocessingDocument sourceDoc = WordprocessingDocument.Open(sourcePath, false))
        {
            var stylePart = sourceDoc.MainDocumentPart.StyleDefinitionsPart;
            if (stylePart != null)
            {
                var newStylePart = destinationMainPart.AddNewPart<StyleDefinitionsPart>();
                newStylePart.FeedData(stylePart.GetStream());
            }
            // Copy headers, footers, themes, fonts, etc., as needed
            // For simplicity, this example copies only styles
        }
    }

    private static Body ExtractPagesContent(string docPath, int pageCount)
    {
        // For demo purposes, this function extracts the first N paragraphs,
        // assuming each paragraph roughly corresponds to a page.
        // In production, you'd need a more robust approach, possibly using WordprocessingML
        // layout calculations or bookmarks.

        using (WordprocessingDocument doc = WordprocessingDocument.Open(docPath, false))
        {
            Body body = doc.MainDocumentPart.Document.Body;
            Body newBody = new Body();

            int paragraphsToCopy = 0;
            int totalParagraphs = body.Elements<Paragraph>().Count();

            foreach (var para in body.Elements<Paragraph>())
            {
                newBody.AppendChild(para.CloneNode(true));
                paragraphsToCopy++;
                // Roughly assume 1 paragraph per page; adjust as needed
                if (paragraphsToCopy >= pageCount * 20) // Example: 20 paragraphs per page
                    break;
            }

            return newBody;
        }
    }

    private static Body ExtractBodyAndGlossary(string docPath)
    {
        // Extract body content and glossary
        // For simplicity, assume glossary is marked by a specific section or bookmark
        using (WordprocessingDocument doc = WordprocessingDocument.Open(docPath, false))
        {
            Body body = doc.MainDocumentPart.Document.Body;

            Body newBody = new Body();

            // Copy all paragraphs for now; in practice, filter for body + glossary
            foreach (var para in body.Elements<Paragraph>())
            {
                newBody.AppendChild(para.CloneNode(true));
            }

            return newBody;
        }
    }

    private static void AppendContent(MainDocumentPart mainPart, Body contentBody)
    {
        var body = mainPart.Document.Body;
        foreach (var element in contentBody.Elements())
        {
            body.AppendChild(element.CloneNode(true));
        }
    }
}
```

---

### Usage:
```csharp
