### 2. `VoxelTerrain.gd` — Manages chunks and terrain generation

```gdscript
extends Node

const CHUNK_SIZE = Vector3(16, 16, 16)
const RENDER_DISTANCE = 2  # Number of chunks to generate around the player

var chunks = {}
var noise = OpenSimplexNoise.new()

var player

func _ready():
    # Configure noise
    noise.seed = randi()
    noise.octaves = 4
    noise.period = 50.0
    noise.persistence = 0.8

    player = get_node("Player")  # Assumes a Player node exists
    generate_chunks()

func generate_chunks():
    var player_chunk_pos = world_to_chunk(player.global_transform.origin)
    for x in range(-RENDER_DISTANCE, RENDER_DISTANCE + 1):
        for z in range(-RENDER_DISTANCE, RENDER_DISTANCE + 1):
            var chunk_pos = Vector3(x, 0, z) + player_chunk_pos
            load_chunk(chunk_pos)

func load_chunk(chunk_coords):
    var key = str(chunk_coords)
    if chunks.has(key):
        return
    var chunk = preload("res://VoxelChunk.tscn").instance()
    add_child(chunk)
    chunk.translation = chunk_coords * CHUNK_SIZE
    # Generate voxel data
    var voxel_data = []
    for x in range(CHUNK_SIZE.x):
        for y in range(CHUNK_SIZE.y):
            for z in range(CHUNK_SIZE.z):
                var world_x = chunk.translation.x + x
                var world_z = chunk.translation.z + z
                var height = terrain_height(world_x, world_z)
                if y <= height:
                    chunk.set_voxel(x, y, z, 1)  # Block type 1
                else:
                    chunk.set_voxel(x, y, z, 0)
    chunk.generate_mesh()
    chunks[key] = chunk

func terrain_height(x, z):
    # Use noise for heightmap
    var value = noise.get_noise_2d(x / 20.0, z / 20.0)
    var height = int((value + 1) * CHUNK_SIZE.y / 2)
    return height

func world_to_chunk(position):
    return Vector3(
        int(position.x / CHUNK_SIZE.x),
        0,
        int(position.z / CHUNK_SIZE.z)
    )

func _process(delta):
    # Optional: Update chunks based on player movement
    pass
```

