public class ListChecker {

    public static <T> T getSingleOrNull(List<T> list) {
        long size = list.stream().count();

        if (size > 1) {
            throw new IllegalStateException("List has more than one entry");
        } else if (size == 1) {
            // Return the single element
            return list.stream().findFirst().orElse(null);
        } else {
            // List is empty
            return null;
        }
    }
}
