                $this->user->favorites()->create(['name' => $name]);
            }
        } else {
            // Save to session
            $favorites = Session::get('favorites', []);
            if (!in_array($name, $favorites)) {
                $favorites[] = $name;
                Session::put('favorites', $favorites);
            }
        }
    }

    /**
     * Remove a name from favorites
     *
     * @param string $name
     * @return void
     */
