            // Remove from database
            $this->user->favorites()->where('name', $name)->delete();
        } else {
            // Remove from session
            $favorites = Session::get('favorites', []);
            $favorites = array_filter($favorites, fn($fav) => $fav !== $name);
            Session::put('favorites', array_values($favorites));
        }
    }
}
