```python
import math

def solve_quadratic(a, b, c):
    """
    Solves the quadratic equation ax^2 + bx + c = 0.

    Returns:
        A tuple containing the roots. The roots can be real or complex numbers.
    """
    if a == 0:
        if b == 0:
            if c == 0:
                return ("Infinite solutions",)
            else:
                return ("No solution",)
        else:
            # Linear solution
            x = -c / b
            return (x,)

    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        sqrt_disc = math.sqrt(discriminant)
        root1 = (-b + sqrt_disc) / (2*a)
        root2 = (-b - sqrt_disc) / (2*a)
        return (root1, root2)
    elif discriminant == 0:
        root = -b / (2*a)
        return (root,)
    else:
        # Complex roots
        sqrt_disc = math.sqrt(-discriminant)
        real_part = -b / (2*a)
        imaginary_part = sqrt_disc / (2*a)
        root1 = complex(real_part, imaginary_part)
        root2 = complex(real_part, -imaginary_part)
        return (root1, root2)

# Example usage:
# roots = solve_quadratic(1, -3, 2)
# print(roots)  # Output: (2.0, 1.0)
```

This function handles:
- The case when \(a = 0\) (linear or degenerate cases),
- Real roots when the discriminant is positive or zero,
- Complex roots when the discriminant is negative.

