```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredsToken1155 is ERC1155, Ownable {
    // Mapping to keep track of credential metadata
    mapping(uint256 => string) public credentialMetadata;

    // Event emitted when a new credential type is created
    event CredentialCreated(uint256 indexed id, string metadata);

    // Constructor to set base URI
    constructor(string memory baseURI) ERC1155(baseURI) {}

    /**
     * @dev Create a new credential type with metadata.
     * Only the owner can call this function.
     * @param id The token ID representing the credential type.
     * @param metadata The URI or description associated with the credential.
     */
    function createCredential(uint256 id, string memory metadata) external onlyOwner {
        require(bytes(credentialMetadata[id]).length == 0, "Credential already exists");
        credentialMetadata[id] = metadata;
        emit CredentialCreated(id, metadata);
    }

    /**
     * @dev Mint credentials to an address.
     * @param to Address to receive the tokens.
     * @param id Credential type ID.
     * @param amount Number of tokens to mint.
     */
    function mint(address to, uint256 id, uint256 amount) external onlyOwner {
        require(bytes(credentialMetadata[id]).length != 0, "Credential does not exist");
        _mint(to, id, amount, "");
    }

    /**
     * @dev Burn credentials from an address.
     * @param from Address to burn tokens from.
     * @param id Credential type ID.
     * @param amount Number of tokens to burn.
     */
    function burn(address from, uint256 id, uint256 amount) external {
        // Only the owner of tokens can burn their tokens
        require(
            from == msg.sender || isApprovedForAll(from, msg.sender),
            "Not authorized to burn"
        );
        _burn(from, id, amount);
    }

    /**
     * @dev Override URI to provide metadata for each credential type.
     */
    function uri(uint256 id) public view override returns (string memory) {
        string memory baseURI = super.uri(id);
        string memory metadata = credentialMetadata[id];
        if (bytes(metadata).length > 0) {
            return metadata;
        } else {
            return baseURI;
        }
    }
}
```

### Key Features:
- **Create Credential Types:** Only the contract owner can create new credential types with associated metadata.
- **Minting:** Owner can mint credentials to users.
- **Burning:** Users or approved parties can burn credentials.
- **Metadata Management:** Each credential type has associated metadata (URI or description).
- **Access Control:** Uses Ownable for administrative functions.

### Usage:
1. Deploy the contract with a base URI.
2. Use `createCredential` to define different credential types.
3. Use `mint` to distribute credentials.
4. Users can burn their credentials if needed.

### Notes:
- You can extend this logic with role-based access control (e.g., OpenZeppelin's AccessControl) for more granular permissions.
- The `uri` function can be customized to return IPFS links or other off-chain metadata.

