Certainly! Implementing a full TCP stack is complex, but I can help you get started with parsing and handling TCP segments within an IPv4 payload using TypeScript. Below is a simplified example that:

- Parses the IPv4 header from your `Uint8Array`.
- Extracts the TCP segment from the IPv4 payload.
- Parses the TCP header.
- Provides a basic structure to handle TCP segments.

This example assumes you already have the IPv4 payload as a `Uint8Array`. If you want to send or receive TCP data, you'd typically need to handle sequence numbers, acknowledgments, flags, and more, but for now, we'll focus on parsing and basic structure.

```typescript
// Define interfaces for IPv4 and TCP headers
interface IPv4Header {
  version: number;
  headerLength: number;
  totalLength: number;
  protocol: number;
  sourceIp: string;
  destinationIp: string;
  payload: Uint8Array;
}

interface TCPHeader {
  sourcePort: number;
  destinationPort: number;
  sequenceNumber: number;
  acknowledgmentNumber: number;
  dataOffset: number;
  flags: {
    ns: boolean;
    cwr: boolean;
    ece: boolean;
    urg: boolean;
    ack: boolean;
    psh: boolean;
    rst: boolean;
    syn: boolean;
    fin: boolean;
  };
  windowSize: number;
  checksum: number;
  urgentPointer: number;
  options?: Uint8Array;
  data: Uint8Array;
}

// Helper function to parse IPv4 header
function parseIPv4Header(packet: Uint8Array): IPv4Header | null {
  if (packet.length < 20) {
    console.error('Packet too short for IPv4 header');
    return null;
  }

  const versionAndHeaderLength = packet[0];
  const version = versionAndHeaderLength >> 4;
  const headerLength = (versionAndHeaderLength & 0x0f) * 4;

  if (version !== 4) {
    console.error('Not an IPv4 packet');
    return null;
  }

  const totalLength = (packet[2] << 8) | packet[3];
  const protocol = packet[9];

  const sourceIp = `${packet[12]}.${packet[13]}.${packet[14]}.${packet[15]}`;
  const destinationIp = `${packet[16]}.${packet[17]}.${packet[18]}.${packet[19]}`;

  const payload = packet.slice(headerLength, totalLength);

  return {
    version,
    headerLength,
    totalLength,
    protocol,
    sourceIp,
    destinationIp,
    payload,
  };
}

// Helper function to parse TCP header
function parseTCPHeader(tcpSegment: Uint8Array): TCPHeader | null {
  if (tcpSegment.length < 20) {
    console.error('TCP segment too short');
    return null;
  }

  const sourcePort = (tcpSegment[0] << 8) | tcpSegment[1];
  const destinationPort = (tcpSegment[2] << 8) | tcpSegment[3];
  const sequenceNumber = 
    (tcpSegment[4] << 24) |
    (tcpSegment[5] << 16) |
    (tcpSegment[6] << 8) |
    tcpSegment[7];

  const acknowledgmentNumber = 
    (tcpSegment[8] << 24) |
    (tcpSegment[9] << 16) |
    (tcpSegment[10] << 8) |
    tcpSegment[11];

  const dataOffsetAndFlags = tcpSegment[12];
  const dataOffset = (dataOffsetAndFlags >> 4) * 4;

  const flagsByte = tcpSegment[13];
  const flags = {
    ns: (dataOffsetAndFlags & 0x01) !== 0,
    cwr: (flagsByte & 0x80) !== 0,
    ece: (flagsByte & 0x40) !== 0,
    urg: (flagsByte & 0x20) !== 0,
    ack: (flagsByte & 0x10) !== 0,
    psh: (flagsByte & 0x08) !== 0,
    rst: (flagsByte & 0x04) !== 0,
    syn: (flagsByte & 0x02) !== 0,
    fin: (flagsByte & 0x01) !== 0,
  };

  const windowSize = (tcpSegment[14] << 8) | tcpSegment[15];
  const checksum = (tcpSegment[16] << 8) | tcpSegment[17];
  const urgentPointer = (tcpSegment[18] << 8) | tcpSegment[19];

  const options = dataOffset > 20 ? tcpSegment.slice(20, dataOffset) : undefined;
  const data = tcpSegment.slice(dataOffset);

  return {
    sourcePort,
    destinationPort,
    sequenceNumber,
    acknowledgmentNumber,
    dataOffset,
    flags,
    windowSize,
    checksum,
    urgentPointer,
    options,
    data,
  };
}

// Main function to parse the IPv4 packet and TCP segment
function parsePacket(packet: Uint8Array): void {
  const ipv4Header = parseIPv4Header(packet);
  if (!ipv4Header) {
    console.error('Failed to parse IPv4 header');
    return;
  }

  if (ipv4Header.protocol !== 6) { // TCP protocol number is 6
    console.log('Not a TCP packet');
    return;
  }

  const tcpSegment = ipv4Header.payload;
  const tcpHeader = parseTCPHeader(tcpSegment);
  if (!tcpHeader) {
    console.error('Failed to parse TCP header');
    return;
  }

  console.log('Parsed TCP segment:', tcpHeader);
  // You can now handle the TCP data (tcpHeader.data)
}

// Example usage:
// Assume you have a Uint8Array named `packetData` containing the IPv4 packet
// parsePacket(packetData);
```

### Notes:
- This code focuses on parsing and does **not** handle TCP connection management, retransmission, congestion control, etc.
- For real applications, you'd need to compute and verify checksums, handle TCP options, manage state, and implement the TCP finite state machine.
- You may also want to integrate with a network interface or raw socket API to send/receive packets, which is platform-dependent.

