    for (int j = -KERNEL_RADIUS; j <= KERNEL_RADIUS; ++j) {
        int y = int(gid.y) + j;
        y = clamp(y, 0, int(params.height) - 1);
        float weight = gaussianKernel[j + KERNEL_RADIUS];

        // Read from the horizontally blurred image
