    }

    // Since the above code performs a single pass, for a full separable Gaussian blur,
    // you'd typically run the kernel twice:
    // 1. Horizontal pass: store result in a temporary buffer
    // 2. Vertical pass: read from the temporary buffer and write to the output

    // For demonstration, here's a simplified combined kernel that performs a single pass
    // assuming the input is already blurred horizontally or vertically.

    // Write the result
    outTexture.write(sum, gid);
}
