---

### 1. Backend: Node.js + Express + PostgreSQL

**Prerequisites:**
- Node.js installed
- PostgreSQL installed and running
- Create a database named `todolist`

**Setup:**

```bash
# Create project directory
mkdir perntodo
cd perntodo

# Initialize Node project
npm init -y

# Install dependencies
npm install express cors pg
```

**Create a server file: `server.js`**

```js
const express = require('express');
const cors = require('cors');
const { Pool } = require('pg');

const app = express();
const port = 5000;

// Middleware
app.use(cors());
app.use(express.json()); // for parsing application/json

// PostgreSQL connection pool
const pool = new Pool({
  user: 'your_pg_username',      // replace with your PostgreSQL username
  host: 'localhost',
  database: 'todolist',          // your database name
  password: 'your_pg_password',  // replace with your PostgreSQL password
  port: 5432,
});

// Create table if not exists
pool.query(`
  CREATE TABLE IF NOT EXISTS todos (
    id SERIAL PRIMARY KEY,
    description TEXT NOT NULL,
    completed BOOLEAN DEFAULT FALSE
  );
`, (err) => {
  if (err) console.error('Error creating table:', err);
});

// Routes

// Get all todos
app.get('/todos', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM todos ORDER BY id DESC');
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Add a new todo
app.post('/todos', async (req, res) => {
  const { description } = req.body;
  if (!description) {
    return res.status(400).json({ error: 'Description is required' });
  }
  try {
    const result = await pool.query(
      'INSERT INTO todos (description) VALUES ($1) RETURNING *',
      [description]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Update a todo (toggle completed)
app.put('/todos/:id', async (req, res) => {
  const { id } = req.params;
  try {
    // Toggle completed status
    const result = await pool.query(
      `UPDATE todos SET completed = NOT completed WHERE id = $1 RETURNING *`,
      [id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Delete a todo
app.delete('/todos/:id', async (req, res) => {
  const { id } = req.params;
  try {
    await pool.query('DELETE FROM todos WHERE id = $1', [id]);
    res.json({ message: 'Todo deleted' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(port, () => {
  console.log(`Server listening at http://localhost:${port}`);
});
```

**Note:** Replace `'your_pg_username'` and `'your_pg_password'` with your PostgreSQL credentials.

---

### 2. Frontend: React

**Setup:**

```bash
# In the same project directory
npx create-react-app client
cd client
npm start
```

**Create a simple To-Do App in `src/App.js`:**

```jsx
import React, { useState, useEffect } from 'react';

function App() {
  const [todos, setTodos] = useState([]);
  const [newTodo, setNewTodo] = useState('');

  const fetchTodos = async () => {
    const res = await fetch('http://localhost:5000/todos');
    const data = await res.json();
    setTodos(data);
  };

  useEffect(() => {
    fetchTodos();
  }, []);

  const addTodo = async () => {
    if (!newTodo) return;
    await fetch('http://localhost:5000/todos', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ description: newTodo }),
    });
    setNewTodo('');
    fetchTodos();
  };

  const toggleComplete = async (id) => {
    await fetch(`http://localhost:5000/todos/${id}`, {
      method: 'PUT',
    });
    fetchTodos();
  };

  const deleteTodo = async (id) => {
    await fetch(`http://localhost:5000/todos/${id}`, {
      method: 'DELETE',
    });
    fetchTodos();
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>To-Do List</h1>
      <input
        type="text"
        value={newTodo}
        onChange={(e) => setNewTodo(e.target.value)}
        placeholder="New task..."
      />
      <button onClick={addTodo}>Add</button>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id} style={{ marginTop: 10 }}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => toggleComplete(todo.id)}
            />
            <span
              style={{
                textDecoration: todo.completed ? 'line-through' : 'none',
                marginLeft: 8,
              }}
            >
              {todo.description}
            </span>
            <button
              onClick={() => deleteTodo(todo.id)}
              style={{ marginLeft: 10 }}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

---

### 3. Run the Application

- **Start the backend server:**

```bash
node server.js
```

- **Start the React frontend:**

```bash
cd client
npm start
```

Open your browser at `http://localhost:3000` to see your To-Do app in action.

---

### Notes:
- Make sure your PostgreSQL server is running.
- Adjust database credentials as needed.
- For production, consider adding error handling, input validation, and styling.

