Please note:
- This is a simplified example to illustrate the approach.
- You need to train your neural network weights separately (e.g., using Python/TensorFlow) and then embed them into the Vitis HLS code.
- The code assumes input images are 28x28 grayscale pixels flattened into a 784-element array.
- For production, consider adding proper data normalization, activation functions, and memory management.

---

### Vitis HLS Example for MNIST Digit Classifier

```cpp
#include <ap_fixed.h>
#include <hls_stream.h>

#define INPUT_SIZE 784
#define HIDDEN_SIZE 128
#define OUTPUT_SIZE 10

// Fixed-point data type for inputs, weights, and activations
typedef ap_fixed<16, 8> data_t;

// Layer weights and biases
// These should be initialized with trained model parameters
// For demonstration, initialized with dummy values
// In practice, replace these with actual trained weights

// Input to Hidden Layer Weights [INPUT_SIZE x HIDDEN_SIZE]
data_t w_input_hidden[INPUT_SIZE][HIDDEN_SIZE];

// Hidden Layer Biases
data_t b_hidden[HIDDEN_SIZE];

// Hidden to Output Layer Weights [HIDDEN_SIZE x OUTPUT_SIZE]
data_t w_hidden_output[HIDDEN_SIZE][OUTPUT_SIZE];

// Output Layer Biases
data_t b_output[OUTPUT_SIZE];

// Activation function (ReLU)
data_t relu(data_t x) {
    return (x > 0) ? x : 0;
}

// Softmax approximation for output (optional, for simplicity we use argmax)
void softmax(data_t input[OUTPUT_SIZE], data_t output[OUTPUT_SIZE]) {
    // Simple softmax implementation
    data_t max = input[0];
    for (int i = 1; i < OUTPUT_SIZE; i++) {
        if (input[i] > max)
            max = input[i];
    }

    data_t sum = 0;
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] = hls::exp(input[i] - max);
        sum += output[i];
    }

    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] /= sum;
    }
}

// Top-level function
extern "C" {
void mnist_nn(
    const data_t input[INPUT_SIZE],
    int &predicted_label
) {
#pragma HLS INTERFACE mode=axis port=input
#pragma HLS INTERFACE mode=s_axilite port=predicted_label
#pragma HLS INTERFACE mode=s_axilite port=return

    // Intermediate layer buffers
    data_t hidden_layer[HIDDEN_SIZE];
    data_t output_layer[OUTPUT_SIZE];

    // Compute hidden layer
    for (int i = 0; i < HIDDEN_SIZE; i++) {
#pragma HLS PIPELINE
        data_t sum = b_hidden[i];
        for (int j = 0; j < INPUT_SIZE; j++) {
            sum += input[j] * w_input_hidden[j][i];
        }
        hidden_layer[i] = relu(sum);
    }

    // Compute output layer
    for (int i = 0; i < OUTPUT_SIZE; i++) {
#pragma HLS PIPELINE
        data_t sum = b_output[i];
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            sum += hidden_layer[j] * w_hidden_output[j][i];
        }
        output_layer[i] = sum;
    }

    // Optionally, apply softmax (not necessary if only argmax is used)
    // data_t softmax_out[OUTPUT_SIZE];
    // softmax(output_layer, softmax_out);

    // Find predicted label (index with max value)
    data_t max_val = output_layer[0];
    int max_idx = 0;
    for (int i = 1; i < OUTPUT_SIZE; i++) {
#pragma HLS PIPELINE
        if (output_layer[i] > max_val) {
            max_val = output_layer[i];
            max_idx = i;
        }
    }

    predicted_label = max_idx;
}
}
```

---

### Notes:
- **Training & Weight Initialization:** You need to train your neural network (e.g., with TensorFlow or PyTorch) and export the weights and biases. Then, embed them into the code as constants or load from memory.
- **Optimization:** For better performance, consider unrolling loops, using burst access for weights, or applying more efficient fixed-point quantization.
- **Activation Functions:** ReLU is used here for simplicity; you could replace or extend with other functions if needed.
- **Dataset Preprocessing:** Normalize input images to match training conditions (e.g., scale pixel values to [0,1]).

---

This code provides a starting point to implement an MNIST classifier in Vitis HLS. You can customize and optimize it further based on your hardware resources and application requirements.

