Certainly! Here's a simple implementation of a basic Recurrent Neural Network (RNN) in plain TypeScript. This example demonstrates how an RNN processes a sequence of inputs to produce outputs, with minimal features for clarity.

```typescript
// Define a simple RNN class
class RNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;

  // Weight matrices
  wxh: number[][]; // input to hidden
  whh: number[][]; // hidden to hidden
  why: number[][]; // hidden to output

  // Hidden state
  hPrev: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;

    // Initialize weights with small random values
    this.wxh = this.randomMatrix(inputSize, hiddenSize);
    this.whh = this.randomMatrix(hiddenSize, hiddenSize);
    this.why = this.randomMatrix(hiddenSize, outputSize);

    // Initialize previous hidden state to zeros
    this.hPrev = new Array(hiddenSize).fill(0);
  }

  // Helper to create a matrix with small random values
  private randomMatrix(rows: number, cols: number): number[][] {
    const matrix: number[][] = [];
    for (let i = 0; i < rows; i++) {
      const row: number[] = [];
      for (let j = 0; j < cols; j++) {
        row.push(Math.random() * 0.1 - 0.05); // values between -0.05 and 0.05
      }
      matrix.push(row);
    }
    return matrix;
  }

  // Matrix-vector multiplication
  private matVecMul(matrix: number[][], vec: number[]): number[] {
    const result: number[] = [];
    for (let i = 0; i < matrix.length; i++) {
      let sum = 0;
      for (let j = 0; j < vec.length; j++) {
        sum += matrix[i][j] * vec[j];
      }
      result.push(sum);
    }
    return result;
  }

  // Element-wise addition
  private vecAdd(a: number[], b: number[]): number[] {
    return a.map((val, idx) => val + b[idx]);
  }

  // Apply tanh activation
  private tanh(x: number): number {
    return Math.tanh(x);
  }

  // Forward pass for one input vector
  public step(input: number[]): { output: number[]; hidden: number[] } {
    // Compute hidden state: h_t = tanh(Wxh * x_t + Whh * h_{t-1})
    const wxh_x = this.matVecMul(this.wxh, input);
    const whh_h = this.matVecMul(this.whh, this.hPrev);
    const sumHidden = this.vecAdd(wxh_x, whh_h);
    const h = sumHidden.map((val) => this.tanh(val));

    // Compute output: y_t = Why * h_t
    const y_raw = this.matVecMul(this.why, h);
    // For simplicity, no activation on output (can add softmax, sigmoid, etc.)

    // Update hidden state
    this.hPrev = h;

    return { output: y_raw, hidden: h };
  }
}

// Example usage:
const inputSize = 3;
const hiddenSize = 4;
const outputSize = 2;

const rnn = new RNN(inputSize, hiddenSize, outputSize);

// Example input sequence
const sequence: number[][] = [
  [1, 0, 1],
  [0, 1, 0],
  [1, 1, 0],
];

// Process the sequence
sequence.forEach((input, index) => {
  const { output, hidden } = rnn.step(input);
  console.log(`Step ${index + 1}`);
  console.log('Input:', input);
  console.log('Hidden state:', hidden);
  console.log('Output:', output);
  console.log('------------------------');
});
```

### How it works:
- The `RNN` class initializes weight matrices with small random values.
- The `step` method takes an input vector, computes the new hidden state using the previous hidden state, and produces an output.
- You can feed a sequence of inputs to see how the RNN updates its states.

### Notes:
- This is a very simple implementation without training or loss functions.
- For real applications, you'd want to add training, data normalization, and more sophisticated activation functions.
- You can extend this code to include backpropagation, training loops, and other features as needed.

